// LinkLibraryFiles attaches each upload to the library file it served.
//
// UPDATE @@table u
//
//	 SET library_file_id = lf.id
//	FROM library_files lf
//
// WHERE u.library_file_id IS NULL
//
//	AND u.file_data_inode IS NOT NULL
//	AND lf.file_data_inode = u.file_data_inode
//	AND lf.file_data_size_bytes = u.file_data_size_bytes
func (s soulseekUploadDo) LinkLibraryFiles() (rowsAffected int64, err error) {
	var generateSQL strings.Builder
	generateSQL.WriteString("UPDATE soulseek_uploads u SET library_file_id = lf.id FROM library_files lf WHERE u.library_file_id IS NULL AND u.file_data_inode IS NOT NULL AND lf.file_data_inode = u.file_data_inode AND lf.file_data_size_bytes = u.file_data_size_bytes ")

	var executeSQL *gorm.DB
	executeSQL = s.UnderlyingDB().Exec(generateSQL.String()) // ignore_security_alert
	rowsAffected = executeSQL.RowsAffected
	err = executeSQL.Error

	return
}

